# ----------------------------------------------------------------------
# Output formatting
# ----------------------------------------------------------------------
DEFAULT_FIELDS = set("fks")
DEFAULT_EXTRAS = set("F") | {"anonymous", "pseudo", "subparser"}
# Kinds enabled by default for C
DEFAULT_KINDS_C = set("defghmstuv")


def _limit_pattern(pattern, limit):
    if limit <= 0:
        return pattern
    # The pattern format is /^...$/ . We cut off the inside if too long.
    if pattern.startswith("/^") and pattern.endswith("$/"):
        inner = pattern[2:-2]
        if len(inner) > limit:
            inner = inner[:limit]
            return "/^" + inner + "/"
    return pattern


def format_tag_uctags(tag, fields, pattern_limit):
    line = [tag.name, tag.input_file]
    pattern = _limit_pattern(tag.pattern, pattern_limit)
    # ex cmd separator:  <pattern>;"
    line.append(pattern + ';"')
    # Fields:
    # 'k' = kind single letter (no prefix in u-ctags)
    if "k" in fields:
        line.append(tag.kind)
    elif "K" in fields:
        line.append(tag.kind_long)
    # Scope: s
    if "s" in fields and tag.scope_name:
        line.append(f"{tag.scope_kind}:{tag.scope_name}")
    # typeref
    if "t" in fields and tag.typeref:
        line.append("typeref:" + tag.typeref)
    # signature
    if "S" in fields and tag.signature:
        line.append("signature:" + tag.signature)
    # line number
    if "n" in fields:
        line.append("line:" + str(tag.line_no))
    # language
    if "l" in fields:
        line.append("language:" + tag.language)
    # end line
    if "e" in fields and tag.end_line:
        line.append("end:" + str(tag.end_line))
    # roles
    if "r" in fields:
        line.append("roles:" + tag.roles)
    # file scope
    if "f" in fields and tag.file_scope:
        line.append("file:")
    return "\t".join(line)


def format_tag_all_fields(tag, pattern_limit):
    """Format a tag with --fields='*' style prefix-annotated fields."""
    line = [tag.name, tag.input_file]
    pattern = _limit_pattern(tag.pattern, pattern_limit)
    line.append(pattern + ';"')
    line.append("kind:" + tag.kind_long)
    line.append("line:" + str(tag.line_no))
    line.append("language:" + tag.language)
    if tag.typeref:
        line.append("typeref:" + tag.typeref)
    if tag.signature:
        line.append("signature:" + tag.signature)
    line.append("roles:" + tag.roles)
    if tag.end_line:
        line.append("end:" + str(tag.end_line))
    if tag.file_scope:
        line.append("file:")
    return "\t".join(line)


# ----------------------------------------------------------------------
# Output drivers
# ----------------------------------------------------------------------
class Options:
    def __init__(self):
        self.tagfile = None  # default depends on -e
        self.append = False
        self.recurse = False
        self.output_format = "u-ctags"
        self.sort = "yes"
        self.excmd = "mixed"
        self.fields = set(DEFAULT_FIELDS)
        self.fields_explicit = False
        self.extras = set(DEFAULT_EXTRAS)
        self.kinds_C = set(DEFAULT_KINDS_C)
        self.pattern_limit = 96
        self.pseudo_tags = None  # enabled set; None means default
        self.languages_restrict = None  # None -> all
        self.quiet = False
        self.totals = "no"
        self.verbose = False
        self.files_from_L = []
        self.etags_include = []
        self.input_encoding = None
        self.output_encoding = None
        self.tag_relative = None
        self.print_language = False
        self.machinable = False
        self.with_list_header = True
        self.put_field_prefix = False
        self.filter_mode = False
        self.filter_terminator = ""
        self.exclude_patterns = []
        self.maxdepth = -1
        self.language_force = None


def guess_language(filename):
    base = os.path.basename(filename)
    low = base.lower()
    _, ext = os.path.splitext(base)
    ext = ext.lower()
    # Very minimal guesser.
    if ext in (".c", ".h"):
        return "C"
    if ext in (".cc", ".cpp", ".cxx", ".c++", ".hh", ".hpp", ".hxx", ".h++"):
        return "C++"
    if ext in (".py", ".pyx"):
        return "Python"
    if ext == ".js":
        return "JavaScript"
    if ext == ".java":
        return "Java"
    if ext == ".go":
        return "Go"
    if ext == ".rs":
        return "Rust"
    if ext == ".rb":
        return "Ruby"
    if ext in (".pl", ".pm"):
        return "Perl"
    if ext == ".php":
        return "PHP"
    if ext == ".sh":
        return "Sh"
    if ext in (".yml", ".yaml"):
        return "Yaml"
    if ext == ".json":
        return "JSON"
    if base == "Makefile" or ext == ".mk":
        return "Make"
    return None


def parse_file(filename, options):
    lang = options.language_force
    if lang in (None, "auto"):
        lang = guess_language(filename)
    if lang is None:
        return []
    if options.languages_restrict is not None and \
       lang not in options.languages_restrict:
        return []
    try:
        with open(filename, "r", encoding="utf-8", errors="replace") as f:
            text = f.read()
    except (OSError, IOError) as e:
        sys.stderr.write(
            f"{PROG_NAME}: Warning: cannot open input file "
            f"\"{filename}\" : {e.strerror or str(e)}\n")
        return []
    if lang == "C":
        parser = CParser(filename, text, options.kinds_C,
                         options.extras, options.pattern_limit)
        parser.parse()
        return parser.tags
    # For other languages, fall back to no tags
    return []


def iter_input_files(options, files):
    out = []
    # Pre-pend files from -L
    for Lfile in options.files_from_L:
        if Lfile == "-":
            for line in sys.stdin:
                p = line.rstrip("\n\r")
                if p:
                    out.append(p)
        else:
            try:
                with open(Lfile, "r") as f:
                    for line in f:
                        p = line.rstrip("\n\r")
                        if p:
                            out.append(p)
            except OSError as e:
                sys.stderr.write(
                    f"{PROG_NAME}: error opening {Lfile}: {e}\n")
    out.extend(files)
    result = []
    for f in out:
        if os.path.isdir(f):
            if options.recurse:
                for root, dirs, fnames in os.walk(f):
                    for fn in fnames:
                        result.append(os.path.join(root, fn))
            else:
                # Skip directory
                continue
        else:
            result.append(f)
    return result

