def _limit_pattern(pattern, limit):
    if limit <= 0:
        return pattern
    # The pattern format is /^...$/ . We cut off the inside if too long.
    if pattern.startswith("/^") and pattern.endswith("$/"):
        inner = pattern[2:-2]
        if len(inner) > limit:
            inner = inner[:limit]
            return "/^" + inner + "/"
    return pattern


def format_tag_uctags(tag, fields, pattern_limit):
    line = [tag.name, tag.input_file]
    pattern = _limit_pattern(tag.pattern, pattern_limit)
    # ex cmd separator:  <pattern>;"
    line.append(pattern + ';"')
    # Fields:
    # 'k' = kind single letter (no prefix in u-ctags)
    if "k" in fields:
        line.append(tag.kind)
    elif "K" in fields:
        line.append(tag.kind_long)
    # Scope: s
    if "s" in fields and tag.scope_name:
        line.append(f"{tag.scope_kind}:{tag.scope_name}")
    # typeref
    if "t" in fields and tag.typeref:
        line.append("typeref:" + tag.typeref)
    # signature
    if "S" in fields and tag.signature:
        line.append("signature:" + tag.signature)
    # line number
    if "n" in fields:
        line.append("line:" + str(tag.line_no))
    # language
    if "l" in fields:
        line.append("language:" + tag.language)
    # end line
    if "e" in fields and tag.end_line:
        line.append("end:" + str(tag.end_line))
    # roles
    if "r" in fields:
        line.append("roles:" + tag.roles)
    # file scope
    if "f" in fields and tag.file_scope:
        line.append("file:")
    return "\t".join(line)


def format_tag_all_fields(tag, pattern_limit):
    """Format a tag with --fields='*' style prefix-annotated fields."""
    line = [tag.name, tag.input_file]
    pattern = _limit_pattern(tag.pattern, pattern_limit)
    line.append(pattern + ';"')
    line.append("kind:" + tag.kind_long)
    line.append("line:" + str(tag.line_no))
    line.append("language:" + tag.language)
    if tag.typeref:
        line.append("typeref:" + tag.typeref)
    if tag.signature:
        line.append("signature:" + tag.signature)
    line.append("roles:" + tag.roles)
    if tag.end_line:
