# Writers
# ----------------------------------------------------------------------
def sort_tags(tags, mode):
    if mode == "no":
        return tags
    if mode == "foldcase":
        key = lambda t: (t.name.lower(), t.input_file, t.line_no)
    else:
        key = lambda t: (t.name, t.input_file, t.line_no)
    return sorted(tags, key=key)


def write_uctags(out, pseudo_lines, tags, options):
    if "p" in options.extras or "pseudo" in options.extras:
        for line in pseudo_lines:
            out.write(line + "\n")
    fields = set(options.fields)
    for t in sort_tags(tags, options.sort):
        # Filter file-scope tags if F not in extras
        if t.file_scope and ("F" not in options.extras and
                              "fileScope" not in options.extras):
            continue
        out.write(format_tag_uctags(t, fields, options.pattern_limit)
                  + "\n")


def write_xref(out, tags, options):
    for t in sort_tags(tags, options.sort):
        if t.file_scope and ("F" not in options.extras and
                              "fileScope" not in options.extras):
            continue
        # Column widths: name(16), kind(12), line(4d), file, src
        out.write(f"{t.name:<16s} {t.kind_long:<12s} {t.line_no:4d} "
                  f"{t.input_file} {t.src_line}\n")


def write_etags(out, filename, tags):
    # Group tags by filename
    groups = {}
    order = []
    for t in tags:
        if t.input_file not in groups:
            order.append(t.input_file)
            groups[t.input_file] = []
        groups[t.input_file].append(t)
    for fn in order:
        block = []
        # offset map
        # Read file to compute offsets for each line number
        try:
            with open(fn, "rb") as f:
                data = f.read()
        except OSError:
            data = b""
        # Compute offsets of each line start
        offsets = [0]
        for i, b in enumerate(data):
            if b == 0x0A:
                offsets.append(i + 1)
        for t in groups[fn]:
            # etags entry: <src_line><name>line,offset
            line = t.src_line
            # Include prefix of src_line up to and including name
            name_idx = line.find(t.name)
            if name_idx == -1:
                prefix = line
            else:
                prefix = line[:name_idx + len(t.name)]
            off = offsets[t.line_no - 1] if t.line_no - 1 < len(offsets) else 0
            block.append(f"{prefix}\x7f{t.name}\x01{t.line_no},{off}")
        body = "\n".join(block) + ("\n" if block else "")
        out.write("\x0c\n")
        out.write(f"{fn},{len(body)}\n")
        out.write(body)


def write_json(out, tags, options):
    import json
    for t in sort_tags(tags, options.sort):
        if t.file_scope and ("F" not in options.extras and
                              "fileScope" not in options.extras):
            continue
        obj = {
            "_type": "tag",
            "name": t.name,
            "path": t.input_file,
            "pattern": t.pattern,
            "kind": t.kind_long,
        }
        if t.scope_name:
            obj["scope"] = t.scope_name
            obj["scopeKind"] = t.scope_kind
        if t.typeref:
            obj["typeref"] = t.typeref
        if t.signature:
            obj["signature"] = t.signature
        if t.file_scope:
            obj["file"] = True
        out.write(json.dumps(obj) + "\n")


