    # Build field-description lines for enabled fields
    for letter, fname, enabled, lang, jstype, fixed, op, ver, desc in FIELDS:
        if lang != "NONE":
            continue
        if fname == "NONE":
            continue
        if (letter not in options.fields and
                fname not in options.fields):
            continue
        tags.append(f"!_TAG_FIELD_DESCRIPTION\t{fname}\t/{desc}/")
    # Extra description
    for letter, ename, enabled, lang, fixed, ver, desc in EXTRAS:
        if lang != "NONE":
            continue
        if ename not in options.extras and letter not in options.extras:
            continue
        tags.append(f"!_TAG_EXTRA_DESCRIPTION\t{ename}\t/{desc}/")
    # Sort pseudos later; build in proper list order matching ctags
    result = []

    # Compose all pseudo tags in a dict keyed by name
    entries = {}

    # TAG_EXTRA_DESCRIPTION entries
    for letter, ename, enabled, lang, fixed, ver, desc in EXTRAS:
        if lang != "NONE":
            continue
        if ename not in options.extras and letter not in options.extras:
            continue
        entries.setdefault("TAG_EXTRA_DESCRIPTION", []).append(
            (ename, desc))

    # TAG_FIELD_DESCRIPTION entries
    for letter, fname, enabled, lang, jstype, fixed, op, ver, desc in FIELDS:
        if lang != "NONE":
            continue
        if fname == "NONE":
            continue
        if (letter not in options.fields and fname not in options.fields):
            continue
        entries.setdefault("TAG_FIELD_DESCRIPTION", []).append(
            (fname, desc))

    entries["TAG_FILE_FORMAT"] = [
        ("2", "extended format; --format=1 will not append ;\" to lines")
    ]
    sorted_num = {"yes": "1", "no": "0", "foldcase": "2"}
    entries["TAG_FILE_SORTED"] = [
        (sorted_num.get(options.sort, "1"),
         "0=unsorted, 1=sorted, 2=foldcase")
    ]
    # Kind descriptions per language
    # Only C for now when enabled
    kind_desc_lines = []
    for letter, name, enabled, refonly, nroles, desc in C_KINDS:
        if letter in options.kinds_C:
            kind_desc_lines.append(("C", f"{letter},{name}", desc))
    if kind_desc_lines:
        entries["TAG_KIND_DESCRIPTION"] = kind_desc_lines
    entries["TAG_OUTPUT_EXCMD"] = [
        (options.excmd, "number, pattern, mixed, or combineV2")
    ]
    entries["TAG_OUTPUT_FILESEP"] = [("slash", "slash or backslash")]
    entries["TAG_OUTPUT_MODE"] = [
        (options.output_format if options.output_format in
         ("u-ctags", "e-ctags") else "u-ctags",
         "u-ctags or e-ctags")
    ]
    entries["TAG_OUTPUT_VERSION"] = [(OUTPUT_VERSION, "current.age")]
    # Parser versions per language
    entries["TAG_PARSER_VERSION"] = [("C", "2.2", "current.age")]
    entries["TAG_PATTERN_LENGTH_LIMIT"] = [
        (str(options.pattern_limit), "0 for no limit")
    ]
    entries["TAG_PROC_CWD"] = [(os.getcwd() + "/", "")]
    entries["TAG_PROGRAM_AUTHOR"] = [("Universal Ctags Team", "")]
    entries["TAG_PROGRAM_NAME"] = [
        ("Universal Ctags", "Derived from Exuberant Ctags")]
    entries["TAG_PROGRAM_URL"] = [(URL, "official site")]
    entries["TAG_PROGRAM_VERSION"] = [
        (CTAGS_VERSION, CTAGS_COMMIT)]
    # Role description per language per kind
    # Only those whose kinds are enabled
    role_desc_lines = []
    for kindname, rolename, desc in C_ROLES:
        # find letter for kindname
        letter = None
        for l, n, *_ in C_KINDS:
            if n == kindname:
                letter = l
                break
        if letter is None:
            continue
        if letter not in options.kinds_C:
            continue
        role_desc_lines.append(("C", kindname, rolename, desc))
    if role_desc_lines:
        entries["TAG_ROLE_DESCRIPTION"] = role_desc_lines

    # Render in sorted order to match observed behavior (alphabetical)
    lines = []

    def emit(name, rows):
        # rows is a list of tuples
        if name in ("TAG_EXTRA_DESCRIPTION", "TAG_FIELD_DESCRIPTION"):
            for (val, desc) in rows:
                lines.append(f"!_{name}\t{val}\t/{desc}/")
        elif name == "TAG_KIND_DESCRIPTION":
            for lang, val, desc in rows:
                lines.append(f"!_{name}!{lang}\t{val}\t/{desc}/")
        elif name == "TAG_ROLE_DESCRIPTION":
            for lang, kindname, rolename, desc in rows:
                lines.append(
                    f"!_{name}!{lang}!{kindname}\t{rolename}\t/{desc}/")
        elif name == "TAG_PARSER_VERSION":
            for lang, val, desc in rows:
                lines.append(f"!_{name}!{lang}\t{val}\t/{desc}/")
        else:
            for val, desc in rows:
                lines.append(f"!_{name}\t{val}\t/{desc}/")

    order = sorted(entries.keys())
    for name in order:
        emit(name, entries[name])
    return lines


