# ----------------------------------------------------------------------
# Parsing command-line
# ----------------------------------------------------------------------

def die(msg, code=1):
    sys.stderr.write(f"{PROG_NAME}: {msg}\n")
    sys.exit(code)


def parse_bool_arg(v, default=True):
    if v is None or v == "":
        return default
    v = v.lower()
    if v in ("yes", "true", "1", "y"):
        return True
    if v in ("no", "false", "0", "n"):
        return False
    return default


def update_flags_set(current, fixed_enabled, spec):
    """Apply a spec like "+k-s" or "*" to the set `current`, returning a
    new set. `fixed_enabled` are always-on flags. Supports '*' = all."""
    if spec is None:
        return current
    if spec == "":
        return set()
    new = set(current)
    i = 0
    mode = None  # '+' or '-' or None (replace)
    if spec[0] in "+-":
        mode = spec[0]
        i = 1
    else:
        new = set(fixed_enabled)
        mode = "+"
    buf = ""
    while i < len(spec):
        c = spec[i]
        if c in "+-":
            # process buf with mode
            if buf:
                if buf == "*":
                    # no-op here, all letters
                    pass
                else:
                    for ch in buf:
                        if mode == "+":
                            new.add(ch)
                        elif mode == "-":
                            new.discard(ch)
                buf = ""
            mode = c
            i += 1
        elif c == "*":
            # enable all
            if mode == "+":
                # caller must union with full set
                new = None
            elif mode == "-":
                new = set()
            i += 1
        else:
            buf += c
            i += 1
    if buf:
        for ch in buf:
            if mode == "+":
                if new is not None:
                    new.add(ch)
            elif mode == "-":
                if new is not None:
                    new.discard(ch)
    return new


def parse_args(argv):
    opts = Options()
    files = []

    # Track whether an output "list" command was requested
    list_action = None
    list_action_arg = None

    def take_value(i, name):
        if i + 1 >= len(argv):
            die(f"option \"{name}\" takes a value")
        return i + 1, argv[i + 1]

    i = 0
    saw_e = False
    saw_x = False
    while i < len(argv):
        a = argv[i]
        if a == "--":
            i += 1
            files.extend(argv[i:])
            break
        if not a.startswith("-"):
            files.append(a)
            # After a file, -f is no longer allowed (ctags behavior)
            i += 1
            continue
        # Long options
        if a.startswith("--"):
            if "=" in a:
                key, _, val = a.partition("=")
            else:
                key, val = a, None
            if key == "--help" or key == "--help-full":
                print_help()
                sys.exit(0)
            elif key == "--version":
                print_version()
                sys.exit(0)
            elif key == "--license":
                print_license()
                sys.exit(0)
            elif key == "--list-languages":
                list_languages(); sys.exit(0)
            elif key == "--list-features":
                list_features(); sys.exit(0)
            elif key == "--list-kinds":
                list_kinds(val or "all"); sys.exit(0)
            elif key == "--list-kinds-full":
                list_kinds_full(val or "all"); sys.exit(0)
            elif key == "--list-pseudo-tags":
                list_pseudo_tags(); sys.exit(0)
            elif key == "--list-fields":
                list_fields(); sys.exit(0)
            elif key == "--list-extras":
                list_extras(); sys.exit(0)
            elif key == "--list-output-formats":
                list_output_formats(); sys.exit(0)
            elif key == "--list-aliases":
                list_aliases(); sys.exit(0)
            elif key == "--list-map-extensions":
                list_map_extensions(val); sys.exit(0)
            elif key == "--list-map-patterns":
                list_map_patterns(val); sys.exit(0)
            elif key == "--list-maps":
                list_maps(val); sys.exit(0)
            elif key == "--list-excludes":
                sys.exit(0)
            elif key == "--list-subparsers":
                sys.exit(0)
            elif key == "--list-params":
                sys.exit(0)
            elif key == "--list-roles":
                sys.exit(0)
            elif key == "--list-regex-flags":
                sys.exit(0)
            elif key == "--list-mline-regex-flags":
                sys.exit(0)
            elif key == "--machinable":
                opts.machinable = parse_bool_arg(val, True)
            elif key == "--with-list-header":
                opts.with_list_header = parse_bool_arg(val, True)
            elif key == "--recurse":
                opts.recurse = parse_bool_arg(val, True)
            elif key == "--append":
                opts.append = parse_bool_arg(val, True)
            elif key == "--format":
                pass
            elif key == "--output-format":
                if val not in ("u-ctags", "e-ctags", "etags", "xref",
                               "json"):
                    die(f"Unknown output format: {val}")
                opts.output_format = val
            elif key == "--sort":
                if val in ("yes", "no", "foldcase"):
                    opts.sort = val
                else:
                    die(f"Invalid value for --sort: {val}")
            elif key == "--excmd":
                opts.excmd = val
            elif key == "--extras":
                opts.extras = update_flags_set(
                    opts.extras, DEFAULT_EXTRAS, val or "") or set()
                if opts.extras is None:
                    opts.extras = set("fFgpqrs") | {
                        "anonymous", "fileScope", "inputFile", "guest",
                        "pseudo", "qualified", "reference", "subparser",
                    }
            elif key.startswith("--extras-"):
                pass  # language-specific extras (ignored)
            elif key == "--fields":
                opts.fields_explicit = True
                r = update_flags_set(opts.fields, DEFAULT_FIELDS, val or "")
                if r is None:
                    opts.fields = set("aCeEfFikKlmnNpPrRsStxzZ")
                else:
                    opts.fields = r
            elif key.startswith("--fields-"):
                pass
            elif key.startswith("--kinds-"):
                lang = key[len("--kinds-"):]
                if lang.lower() in ("c", "all"):
                    r = update_flags_set(opts.kinds_C, DEFAULT_KINDS_C,
                                         val or "")
                    if r is None:
                        opts.kinds_C = set(
                            "defghmstuv" + "lpxzDL")
                    else:
                        opts.kinds_C = r
            elif key == "--pattern-length-limit":
                try:
                    opts.pattern_limit = int(val)
                except (TypeError, ValueError):
                    die(f"Invalid value for --pattern-length-limit: {val}")
            elif key == "--pseudo-tags":
                # Ignored — always emit default set
                pass
            elif key == "--put-field-prefix":
                opts.put_field_prefix = True
            elif key == "--tag-relative":
                opts.tag_relative = val
            elif key == "--language-force":
                opts.language_force = val
            elif key == "--languages":
                if val is None:
                    die("missing value for --languages")
                # Comma-separated, with possible +/-
                # Simplified: if starts with + or -, we can't fully
                # model without a current set. Just set the list.
                if val.startswith("+") or val.startswith("-"):
                    mode = val[0]
                    items = [x for x in val[1:].split(",") if x]
                    if opts.languages_restrict is None:
                        opts.languages_restrict = set(LANGUAGES)
                    if mode == "+":
                        opts.languages_restrict.update(items)
                    else:
                        opts.languages_restrict.difference_update(items)
                else:
                    if val.lower() == "all":
                        opts.languages_restrict = None
                    else:
                        opts.languages_restrict = set(
                            x for x in val.split(",") if x)
            elif key == "--quiet":
                opts.quiet = parse_bool_arg(val, True)
            elif key == "--totals":
                if val is None:
                    opts.totals = "yes"
                else:
                    opts.totals = val
            elif key == "--verbose":
                opts.verbose = parse_bool_arg(val, True)
            elif key == "--links":
                pass
            elif key == "--maxdepth":
                try:
                    opts.maxdepth = int(val)
                except (TypeError, ValueError):
                    die(f"Invalid value for --maxdepth: {val}")
            elif key == "--filter":
                opts.filter_mode = parse_bool_arg(val, True)
            elif key == "--filter-terminator":
                opts.filter_terminator = val or ""
            elif key == "--exclude":
                if val is not None:
                    opts.exclude_patterns.append(val)
            elif key == "--exclude-exception":
                pass
            elif key == "--guess-language-eagerly":
                pass
            elif key == "--etags-include":
                if val is not None:
                    opts.etags_include.append(val)
            elif key == "--input-encoding":
                opts.input_encoding = val
            elif key.startswith("--input-encoding-"):
                pass
            elif key == "--output-encoding":
                opts.output_encoding = val
            elif key == "--if0":
                pass
            elif key == "--line-directives":
                pass
            elif key == "--print-language":
                opts.print_language = True
            elif key == "--options":
                # not supported; ignore
                pass
            elif key == "--options-maybe":
                pass
            elif key == "--optlib-dir":
                pass
            elif key.startswith("--alias-"):
                pass
            elif key == "--langmap":
                pass
            elif key.startswith("--map-"):
                pass
            elif key == "--langdef":
                pass
            elif key.startswith("--kinddef-"):
                pass
            elif key.startswith("--mline-regex-"):
                pass
            elif key.startswith("--regex-"):
                pass
            elif key.startswith("--param-"):
                pass
            elif key.startswith("--roles-"):
                pass
            elif key == "--describe-language":
                # Emit nothing specific
                sys.exit(0)
            else:
                die(f"Unknown option: {key}")
            i += 1
            continue
        # Short options (may be stacked, but most ctags short opts take args)
        if len(a) > 1 and a[0] == "-":
            j = 1
            while j < len(a):
                c = a[j]
                if c == "?":
                    print_help(); sys.exit(0)
                elif c == "h":
                    # -h takes a value
                    if j + 1 < len(a):
                        _val = a[j+1:]
                        j = len(a)
                    else:
                        i, _val = take_value(i, "-h")
                        j = len(a)
                    # ignored
                elif c == "f" or c == "o":
                    if j + 1 < len(a):
                        _val = a[j+1:]
                        j = len(a)
                    else:
                        i, _val = take_value(i, "-" + c)
                        j = len(a)
                    if files:
                        die(f"-{c} option may not follow a file name")
                    opts.tagfile = _val
                elif c == "L":
                    if j + 1 < len(a):
                        _val = a[j+1:]
                        j = len(a)
                    else:
                        i, _val = take_value(i, "-L")
                        j = len(a)
                    opts.files_from_L.append(_val)
                elif c == "D":
                    if j + 1 < len(a):
                        _val = a[j+1:]
                        j = len(a)
                    else:
                        i, _val = take_value(i, "-D")
                        j = len(a)
                elif c == "I":
                    if j + 1 < len(a):
                        _val = a[j+1:]
                        j = len(a)
                    else:
                        i, _val = take_value(i, "-I")
                        j = len(a)
                elif c == "R":
                    opts.recurse = True
                    j += 1
                elif c == "a":
                    opts.append = True
                    j += 1
                elif c == "e":
                    opts.output_format = "etags"
                    saw_e = True
                    j += 1
                elif c == "x":
                    opts.output_format = "xref"
                    saw_x = True
                    j += 1
                elif c == "u":
                    opts.sort = "no"
                    j += 1
                elif c == "n":
                    opts.excmd = "number"
                    j += 1
                elif c == "N":
                    opts.excmd = "pattern"
                    j += 1
                elif c == "B":
                    j += 1
                elif c == "F":
                    j += 1
                elif c == "G":
                    j += 1
