    if not files and not opts.files_from_L and not opts.filter_mode:
        die(f"No files specified. Try \"{PROG_NAME} --help\".")

    actual_files = iter_input_files(opts, files)

    all_tags = []
    n_files = 0
    total_bytes = 0
    total_lines = 0
    t0 = time.time()
    for f in actual_files:
        if not os.path.exists(f):
            sys.stderr.write(
                f"{PROG_NAME}: Warning: cannot open input file "
                f"\"{f}\" : No such file or directory\n")
            continue
        if opts.print_language:
            lang = guess_language(f) or "NONE"
            print(f"{f}: {lang}")
            continue
        try:
            total_bytes += os.path.getsize(f)
        except OSError:
            pass
        try:
            with open(f, "r", encoding="utf-8", errors="replace") as fh:
                total_lines += sum(1 for _ in fh)
        except OSError:
            pass
        tags = parse_file(f, opts)
        all_tags.extend(tags)
        n_files += 1

    if opts.print_language:
        return 0

    # Output
    if opts.tagfile == "-":
        out = sys.stdout
        close_out = False
    else:
        mode = "a" if opts.append else "w"
        out = open(opts.tagfile, mode)
        close_out = True

    if opts.output_format in ("u-ctags", "e-ctags"):
        pseudo_lines = emit_pseudo_tags(opts, {})
        write_uctags(out, pseudo_lines, all_tags, opts)
    elif opts.output_format == "xref":
        write_xref(out, all_tags, opts)
    elif opts.output_format == "etags":
        write_etags(out, opts.tagfile, all_tags)
    elif opts.output_format == "json":
        write_json(out, all_tags, opts)

    if close_out:
        out.close()

    if opts.totals != "no":
        elapsed = time.time() - t0
        kb = total_bytes / 1024.0
        speed = (total_bytes / 1024.0 / elapsed) if elapsed > 0 else 0
        sys.stderr.write(
            f"{n_files} file{'s' if n_files != 1 else ''}, "
            f"{total_lines} lines ({int(kb)} kB) scanned in "
            f"{elapsed:.1f} seconds ({int(speed)} kB/s)\n")
        non_pseudo_tags = len(all_tags)
        sys.stderr.write(
            f"{non_pseudo_tags} tags added to tag file\n")
        if opts.sort != "no":
            sys.stderr.write(
                f"{non_pseudo_tags} tags sorted in {elapsed:.2f} seconds\n")

    return 0


if __name__ == "__main__":
    try:
        sys.exit(main(sys.argv))
