def parse_bool_arg(v, default=True):
    if v is None or v == "":
        return default
    v = v.lower()
    if v in ("yes", "true", "1", "y"):
        return True
    if v in ("no", "false", "0", "n"):
        return False
    return default


def update_flags_set(current, fixed_enabled, spec):
    """Apply a spec like "+k-s" or "*" to the set `current`, returning a
    new set. `fixed_enabled` are always-on flags. Supports '*' = all."""
    if spec is None:
        return current
    if spec == "":
        return set()
    new = set(current)
    i = 0
    mode = None  # '+' or '-' or None (replace)
    if spec[0] in "+-":
        mode = spec[0]
        i = 1
    else:
        new = set(fixed_enabled)
        mode = "+"
    buf = ""
    while i < len(spec):
        c = spec[i]
        if c in "+-":
            # process buf with mode
            if buf:
                if buf == "*":
                    # no-op here, all letters
                    pass
                else:
                    for ch in buf:
                        if mode == "+":
                            new.add(ch)
                        elif mode == "-":
                            new.discard(ch)
                buf = ""
            mode = c
            i += 1
        elif c == "*":
            # enable all
            if mode == "+":
                # caller must union with full set
                new = None
            elif mode == "-":
                new = set()
            i += 1
        else:
            buf += c
            i += 1
    if buf:
        for ch in buf:
            if mode == "+":
                if new is not None:
                    new.add(ch)
            elif mode == "-":
                if new is not None:
                    new.discard(ch)
    return new


